func diskTimeToFull(inputs *Inputs) []Insight {
	var out []Insight
	thresholds := inputs.Thresholds
	for _, member := range members(inputs) {
		if member.System == nil {
			continue
		}
		for _, filesystem := range member.System.Filesystems {
			if filesystem.SizeBytes == 0 {
				continue
			}
			size := float64(filesystem.SizeBytes)
			used := size - float64(min(filesystem.AvailBytes, filesystem.SizeBytes))
			ratio := used / size
			entity := Entity{Kind: "host", ID: member.Member + ":" + filesystem.Role, Href: memberHref(member.Member)}
			labels := map[string]string{"member": member.Member, "role": filesystem.Role}
			usedEvidence := Evidence{Label: "Used", Metric: observability.HistFSRatio, Labels: labels, Value: ratio,
				Unit: "ratio", Comparison: "<", Threshold: threshold(thresholds.DiskUsedWarning)}
			action := Action{Label: "Find what is growing", Command: "du -xh --max-depth=2 " + filesystem.Path + " | sort -h | tail"}
			// Both criteria are evaluated and the worse one wins, under one
			// key per filesystem: crossing the usage warning must not
			// downgrade a disk that fills within hours, nor resolve and
			// reopen the same problem under a new key.
			var candidates []Insight
			if ratio >= thresholds.DiskUsedWarning {
				severity := SeverityWarning
				evidence := usedEvidence
				if ratio >= thresholds.DiskUsedCritical {
					severity = SeverityCritical
					evidence.Threshold = threshold(thresholds.DiskUsedCritical)
				}
				candidates = append(candidates, Insight{Severity: severity, Score: ratio * 100,
					Title: fmt.Sprintf("%s %s filesystem is %.0f%% full", member.Member, filesystem.Role, ratio*100),
					Why: fmt.Sprintf("The %s filesystem (%s) on %s has %s free.", filesystem.Role, filesystem.Path,
						member.Member, bytesText(float64(filesystem.AvailBytes))),
					Evidence: []Evidence{evidence}})
			}
			if ttf, rate, ok := timeToFull(inputs, labels, size, used); ok && ttf < thresholds.DiskTimeToFullWarning {
				severity := SeverityWarning
				limit := thresholds.DiskTimeToFullWarning
				if ttf < thresholds.DiskTimeToFullCritical {
					severity, limit = SeverityCritical, thresholds.DiskTimeToFullCritical
				}
				candidates = append(candidates, Insight{Severity: severity, Score: 1e6 / max(ttf.Hours(), 0.01),
					Title: fmt.Sprintf("%s %s filesystem full in about %s", member.Member, filesystem.Role, roundDuration(ttf)),
					Why: fmt.Sprintf("The %s filesystem on %s grows %s per hour and has %s free, so it fills in about %s.",
						filesystem.Role, member.Member, bytesText(rate*3600), bytesText(size-used), roundDuration(ttf)),
					Evidence: []Evidence{{Label: "Time to full", Value: ttf.Hours(), Unit: "h", Comparison: ">=",
						Threshold: threshold(limit.Hours())},
						{Label: "Growth", Metric: observability.HistFSUsed, Labels: labels, Value: rate * 3600, Unit: "bytes/h"},
						usedEvidence}})
			}
			if len(candidates) == 0 {
				continue
			}
			worst := candidates[0]
			for _, candidate := range candidates[1:] {
				if candidate.Severity.Rank() > worst.Severity.Rank() {
					worst = candidate
				}
			}
			worst.Key, worst.Entity, worst.Actions = "disk:"+entity.ID, entity, []Action{action}
			out = append(out, worst)
		}
	}
	return out
}

// timeToFull fits a least-squares line through the filesystem's used bytes
// over the last six hours of history. It needs at least 30 minutes of data
// and a growing trend.
func timeToFull(inputs *Inputs, labels map[string]string, size, used float64) (time.Duration, float64, bool) {
	if inputs.History == nil {
		return 0, 0, false
	}
	result := inputs.History.Range(observability.HistoryQuery{Metric: observability.HistFSUsed, Labels: labels,
		Start: inputs.Now.Add(-6 * time.Hour), End: inputs.Now, Tier: observability.Tier1m, MaxSeries: 1})
	if len(result.Series) == 0 {
		return 0, 0, false
	}
	points := result.Series[0].Points
	if len(points) < 5 || points[len(points)-1].Time.Sub(points[0].Time) < 30*time.Minute {
		return 0, 0, false
	}
	origin := points[0].Time
	var sumX, sumY, sumXY, sumXX float64
	for _, point := range points {
		x := point.Time.Sub(origin).Seconds()
		sumX += x
		sumY += point.Value
		sumXY += x * point.Value
		sumXX += x * x
	}
	count := float64(len(points))
	denominator := count*sumXX - sumX*sumX
	if denominator == 0 {
		return 0, 0, false
	}
	slope := (count*sumXY - sumX*sumY) / denominator // bytes per second
	if slope <= 0 {
		return 0, 0, false
	}
	seconds := (size - used) / slope
	if seconds > (365 * 24 * time.Hour).Seconds() {
		return 0, 0, false
	}
	return time.Duration(seconds * float64(time.Second)), slope, true
}

history.text:
func newTier(step, retention, interval time.Duration) *tier {
	capacity := int(retention / interval)
	if step > 0 {
		capacity = int(retention / step)
	}
	return &tier{step: step, ring: make([]bucket, max(capacity, 1))}
}

func (t *tier) push(b bucket) {
	index := (t.start + t.size) % len(t.ring)
	if t.size == len(t.ring) {
		t.start = (t.start + 1) % len(t.ring)
	} else {
		t.size++
	}
	t.ring[index] = b
}

func (t *tier) add(at int64, value float64, increase float64, counted bool) {
	if t.step == 0 {
		b := bucket{Start: at}
		b.add(at, value, increase, counted)
		t.push(b)
		return
	}
	stepMillis := t.step.Milliseconds()
	aligned := at - at%stepMillis
	if t.opened && aligned != t.open.Start {
		if aligned < t.open.Start {
			return // out of order; ignore
		}
		t.push(t.open)
		t.opened = false
	}
	if !t.opened {
		t.open = bucket{Start: aligned}
		t.opened = true
	}
	t.open.add(at, value, increase, counted)
}

// buckets returns closed buckets plus the open one, oldest first.
func (t *tier) buckets() []bucket {
	out := make([]bucket, 0, t.size+1)
	for offset := range t.size {
		out = append(out, t.ring[(t.start+offset)%len(t.ring)])
	}
	if t.opened {
		out = append(out, t.open)
	}
	return out
}

type series struct {
	metric  string
	labels  []Label
	counter bool
	last    int64
	// lastValue is the newest raw sample, the baseline of a counter's next
	// increase; sampled reports that there is one.
	lastValue float64
	sampled   bool
	tiers     map[string]*tier
}

// HistoryConfig sizes a History.
type HistoryConfig struct {
	// Interval is the expected sampling interval; it sizes the raw tier.
	Interval time.Duration
	// MaxSeries bounds distinct series; new series beyond it are dropped
	// and counted.
	MaxSeries int
	// StaleAfter releases slots for series that stopped reporting.
	// Zero uses the full history retention.
	StaleAfter time.Duration
}

// History is a bounded in-memory time-series store of key metrics with
// raw -> 1m -> 5m -> 1h downsampling over 14 days. It is safe for concurrent
// use; Append and Range never perform I/O.
type History struct {
	config       HistoryConfig
	mu           sync.RWMutex
	series       map[string]*series
	dropped      uint64
	dropMinutes  map[int64]bool
	newestMinute int64
}

// NewHistory returns an empty store.
func NewHistory(config HistoryConfig) *History {
	if config.Interval <= 0 {
		config.Interval = DefaultHistoryInterval
	}
	if config.MaxSeries <= 0 {
		config.MaxSeries = DefaultHistorySeries
	}
	if config.StaleAfter <= 0 {
		config.StaleAfter = HistoryRetention
	}
	return &History{config: config, series: map[string]*series{}, dropMinutes: map[int64]bool{}}
}

func seriesKey(metric string, labels []Label) string {
	pairs := make([]string, 0, len(labels)*2)
	for _, label := range labels {
		pairs = append(pairs, label.Name, label.Value)
	}
	return Series(metric, pairs...)
}

func sortedLabels(labels []Label) []Label {
	labels = slices.Clone(labels)
	slices.SortFunc(labels, func(left, right Label) int { return cmp.Compare(left.Name, right.Name) })
	return labels
}

func (history *History) newSeries(metric string, labels []Label, counter bool) *series {
	interval := history.config.Interval
	return &series{metric: metric, labels: labels, counter: counter, tiers: map[string]*tier{
		TierRaw: newTier(0, rawRetention, interval),
		Tier1m:  newTier(time.Minute, oneMinuteRetention, interval),
		Tier5m:  newTier(5*time.Minute, fiveMinuteRetention, interval),
		Tier1h:  newTier(time.Hour, HistoryRetention, interval),
	}}
}

// Append stores one batch of samples taken at the same time. NaN and
// infinite values are skipped.
func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

func (history *History) Range(query HistoryQuery) HistoryResult {
	if query.End.IsZero() {
		query.End = time.Now()
	}
	if query.Start.IsZero() {
		query.Start = query.End.Add(-time.Hour)
	}
	chosen := query.Tier
	if chosen == "" {
		chosen = TierFor(query.Start, time.Now())
	}
	if query.MaxSeries <= 0 {
		query.MaxSeries = 64
	}
	query.MaxSeries = min(query.MaxSeries, 512)
	start, end := query.Start.UnixMilli(), query.End.UnixMilli()
	cutoff := time.Now().Add(-HistoryRetention).UnixMilli()
	history.mu.RLock()
	defer history.mu.RUnlock()
	result := HistoryResult{RetentionStart: time.UnixMilli(cutoff).UTC(),
		IntervalSeconds: history.config.Interval.Seconds(), DroppedSeries: history.dropped}
	for minute := range history.dropMinutes {
		if minute >= start/time.Minute.Milliseconds() && minute <= end/time.Minute.Milliseconds() {
			result.Incomplete = true
			break
		}
	}
	keys := slices.Sorted(maps.Keys(history.series))
	for _, key := range keys {
		current := history.series[key]
		if current.metric != query.Metric || !labelsMatch(current.labels, query.Labels) {
			continue
		}
		if query.Rate && !current.counter {
			result.UnsupportedReason = "rate_requires_counter"
			continue
		}
		tierName := chosen
		if query.Tier == "" {
			tierName = current.coveringTier(chosen, start, end, cutoff)
		}
		t, ok := current.tiers[tierName]
		if !ok {
			continue
		}
		out := HistorySeries{Metric: current.metric, Tier: tierName, Labels: labelMap(current.labels)}
		var previous *bucket
		var lastAt int64
		expected := max(history.config.Interval, t.step).Milliseconds()
		for _, b := range t.buckets() {
			if b.lastAt() < cutoff {
				continue
			}
			if b.Start > end {
				break
			}
			if b.Start < start-t.step.Milliseconds() {
				copied := b
				previous = &copied
				continue
			}
			if lastAt != 0 && b.lastAt()-lastAt > 2*expected {
				out.Gaps = true
			}
			lastAt = b.lastAt()
			if query.Rate {
				if previous != nil && b.lastAt() > previous.lastAt() {
					delta := b.Last - previous.Last
					if delta < 0 { // counter reset
						delta = b.Last
					}
					if b.Increased {
						// Growth accumulated per raw sample also counts a
						// reset and recovery inside the bucket.
						delta = b.Increase
					}
					rate := delta / (float64(b.lastAt()-previous.lastAt()) / 1000)
					out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: rate,
						Min: rate, Max: rate})
				}
				copied := b
				previous = &copied
				continue
			}
			value := b.Sum / float64(b.Count)
			if current.counter {
				value = b.Last
			}
			out.Points = append(out.Points, Point{Time: time.UnixMilli(b.Start).UTC(), Value: value,
				Min: b.Min, Max: b.Max, Samples: b.Count})
		}
		out.LastObservedAt = time.UnixMilli(lastAt).UTC()
		out.Stale = end-lastAt > 2*expected
		// A stored series without points in the range does not take one
		// of the result's slots.
		if len(out.Points) == 0 {
			continue
		}
		if len(result.Series) == query.MaxSeries {
			result.Truncated = true
			break
		}
		result.Series = append(result.Series, out)
	}
	return result
}

memory.text:
func memoryPressure(inputs *Inputs) []Insight {
	var out []Insight
	for _, member := range members(inputs) {
		system := member.System
		if system == nil || system.MemTotalBytes == 0 {
			continue
		}
		ratio := 1 - float64(min(system.MemAvailBytes, system.MemTotalBytes))/float64(system.MemTotalBytes)
		if ratio < inputs.Thresholds.MemoryUsedWarning {
			continue
		}
		out = append(out, Insight{Severity: SeverityWarning, Score: ratio * 100,
			Title: fmt.Sprintf("%s memory is %.0f%% used", member.Member, ratio*100),
			Why: fmt.Sprintf("%s has %s of memory available; the kernel may start reclaiming or killing processes.",
				member.Member, bytesText(float64(system.MemAvailBytes))),
			Entity: Entity{Kind: "member", ID: member.Member, Href: memberHref(member.Member)},
			Evidence: []Evidence{{Label: "Memory used", Metric: observability.HistMemoryRatio,
				Labels: map[string]string{"member": member.Member}, Value: ratio, Unit: "ratio", Comparison: "<",
				Threshold: threshold(inputs.Thresholds.MemoryUsedWarning)}},
			Actions: []Action{{Label: "List the largest processes", Command: "ps aux --sort=-rss | head"}}})
	}
	return out
}

summary.text:
// KindPhrase returns "1 hold" or "3 holds" for a kind and count.
func KindPhrase(kind decisionlog.Kind, count int) string {
	nouns, ok := kindNouns[kind]
	if !ok {
		name := strings.ReplaceAll(string(kind), "_", " ")
		nouns = [2]string{name, name}
		if count != 1 {
			return fmt.Sprintf("%d %s decisions", count, name)
		}
		return fmt.Sprintf("1 %s decision", name)
	}
	if count == 1 {
		return "1 " + nouns[0]
	}
	return fmt.Sprintf("%d %s", count, nouns[1])
}

// WindowPhrase renders a window as "hour", "24 hours" or "15 minutes".
func WindowPhrase(window time.Duration) string {
	switch {
	case window == time.Hour:
		return "hour"
	case window%time.Hour == 0:
		return fmt.Sprintf("%d hours", int(window.Hours()))
	case window%time.Minute == 0:
		return fmt.Sprintf("%d minutes", int(window.Minutes()))
	default:
		return window.String()
	}
}

// Summarize writes the paragraph. The same input always yields the same
// text: kinds are ordered by count then name, and only data inside the
// window is used.
func Summarize(input SummaryInput) Summary {
	since := input.Now.Add(-input.Window)
	scope := input.Scope
	if scope == "" {
		scope = "the region"
	}
	summary := Summary{Window: input.Window, Scope: scope, Generated: input.Now, Open: Count(input.Open)}
	var decisions []decisionlog.Decision
	for _, decision := range input.Decisions {
		if !decision.Time.Before(since) && !decision.Time.After(input.Now) {
			decisions = append(decisions, decision)
		}
	}
	decisionlog.SortNewestFirst(decisions)
	summary.Decisions = len(decisions)
	window := WindowPhrase(input.Window)
	var sentences []string
	// A truncated decision query makes the count a lower bound, which a
	// structured consumer must be able to tell apart from an exact count.
	summary.Partial = input.DecisionsTruncated || input.DecisionsPartial || input.ChangesTruncated
	switch {
	case len(decisions) == 0 && input.DecisionsPartial:
		sentences = append(sentences, fmt.Sprintf("In the last %s no decisions were found in %s, but part of the "+
			"history could not be searched%s.", window, scope, unansweredText(input.Unanswered)))
	case len(decisions) == 0:
		sentences = append(sentences, fmt.Sprintf("In the last %s the orchestrator made no recorded decisions in %s.",
			window, scope))
	default:
		counts := map[decisionlog.Kind]int{}
		for _, decision := range decisions {
			counts[decision.Kind]++
		}
		kinds := slices.SortedFunc(maps.Keys(counts), func(left, right decisionlog.Kind) int {
			if order := cmp.Compare(counts[right], counts[left]); order != 0 {
				return order
			}
			return cmp.Compare(left, right)
		})
		var phrases []string
		for index, kind := range kinds {
			if index == 4 {
				rest := 0
				for _, other := range kinds[4:] {
					rest += counts[other]
				}
				phrases = append(phrases, fmt.Sprintf("%d other", rest))
				break
			}
			phrases = append(phrases, KindPhrase(kind, counts[kind]))
		}
		noun := "decisions"
		if len(decisions) == 1 {
			noun = "decision"
		}
		made := fmt.Sprintf("%d %s", len(decisions), noun)
		if input.DecisionsTruncated || input.DecisionsPartial {
			made = "at least " + made
		}
		sentences = append(sentences, fmt.Sprintf("In the last %s the orchestrator made %s in %s: %s.",
			window, made, scope, joinList(phrases)))
		if input.DecisionsPartial {
			sentences = append(sentences, "Part of the history could not be searched"+
				unansweredText(input.Unanswered)+", so these counts are lower bounds.")
		}
		sentences = append(sentences, notable(decisions)...)
	}
	for _, change := range input.Changes {
		if change.Time.Before(since) || change.Time.After(input.Now) {
			continue
		}
		switch change.Type {
		case ChangeOpened:
			summary.Opened++
		case ChangeResolved:
			summary.Resolved++
		}
	}
	if summary.Opened > 0 || summary.Resolved > 0 {
		atLeast := ""
		if input.ChangesTruncated {
			atLeast = "At least "
		}
		sentence := fmt.Sprintf("%s opened and %s resolved", countNoun(summary.Opened, "problem", "problems"),
			countNoun(summary.Resolved, "problem", "problems"))
		if atLeast != "" {
			sentence = atLeast + lowerFirst(sentence)
		}
		if input.AttentionScope != "" {
			sentence += " in " + input.AttentionScope
		}
		sentences = append(sentences, sentence+".")
	}
	open := slices.Clone(input.Open)
	Rank(open)
	where := ""
	if input.AttentionScope != "" {
		where = " in " + input.AttentionScope
	}
	switch {
	case len(open) == 0:
		sentences = append(sentences, "Nothing needs attention"+where+" right now.")
	default:
		var parts []string
		if summary.Open.Critical > 0 {
			parts = append(parts, countNoun(summary.Open.Critical, "critical problem", "critical problems"))
		}
		if summary.Open.Warning > 0 {
			parts = append(parts, countNoun(summary.Open.Warning, "warning", "warnings"))
		}
		if summary.Open.Info > 0 {
			parts = append(parts, countNoun(summary.Open.Info, "note", "notes"))
		}
		verb := "needs"
		if len(open) > 1 {
			verb = "need"
		}
		sentences = append(sentences, fmt.Sprintf("Now %s %s attention%s, most urgently: %s.", joinList(parts), verb,
			where, strings.TrimSuffix(open[0].Title, ".")))
	}
	summary.Sentences = sentences
	summary.Text = strings.Join(sentences, " ")
	return summary
}

func unansweredText(regions []string) string {
	if len(regions) == 0 {
		return ""
	}
	upper := make([]string, len(regions))
	for index, region := range regions {
		upper[index] = strings.ToUpper(region)
	}
	verb := "did"
	return " (" + joinList(upper) + " " + verb + " not answer)"
}

// notable calls out the decisions an operator most wants to hear about,
// newest first, at most three.
func notable(decisions []decisionlog.Decision) []string {
	var out []string
	add := func(sentence string) bool {
		out = append(out, sentence)
		return len(out) < 3
	}
	failed := 0
	for _, decision := range decisions {
		if decision.Status == decisionlog.StatusFailed {
			failed++
		}
	}
	for _, decision := range decisions {
		var sentence string
		switch decision.Kind {
		case decisionlog.KindRollback:
			sentence = "A rollback of " + subjectText(decision) + " was decided" + because(decision) + "."
		case decisionlog.KindQuorumDegraded:
			sentence = "Quorum degraded on " + memberText(decision) + because(decision) + "."
		case decisionlog.KindLeaderChanged:
			sentence = "Authority leadership moved to " + subjectText(decision) + epochText(decision) + "."
		case decisionlog.KindCanaryPromoted, decisionlog.KindRolloutCompleted:
			sentence = upperFirst(KindPhrase(decision.Kind, 1)[2:]) + ": " + subjectText(decision) + "."
		default:
			continue
		}
		if !add(sentence) {
			break
		}
	}
	if failed > 0 && len(out) < 4 {
		out = append(out, countNoun(failed, "decision", "decisions")+" failed.")
	}
	return out
}

func subjectText(decision decisionlog.Decision) string {
	if decision.Subject.Name != "" {
		return decision.Subject.Name
	}
	if decision.Subject.ID != "" {
		return shortID(decision.Subject.ID)
	}
	return "an unnamed subject"
}

func memberText(decision decisionlog.Decision) string {
	if decision.Actor.Member != "" {
		return decision.Actor.Member
	}
	return subjectText(decision)
}

func because(decision decisionlog.Decision) string {
	reason := strings.TrimSuffix(strings.TrimSpace(decision.Reason), ".")
	if reason == "" {
		return ""
	}
	return " because " + lowerFirst(reason)
}

func epochText(decision decisionlog.Decision) string {
	if decision.Epoch == 0 {
		return ""
	}
	return fmt.Sprintf(" (epoch %d)", decision.Epoch)
}

func countNoun(count int, singular, plural string) string {
	if count == 1 {
		return "1 " + singular
	}
	return fmt.Sprintf("%d %s", count, plural)
}

func joinList(items []string) string {
	switch len(items) {
	case 0:
		return ""
	case 1:
		return items[0]
	case 2:
		return items[0] + " and " + items[1]
	default:
		return strings.Join(items[:len(items)-1], ", ") + " and " + items[len(items)-1]
	}
}

func upperFirst(text string) string {
	if text == "" {
		return text
	}
	return strings.ToUpper(text[:1]) + text[1:]
}

func lowerFirst(text string) string {
	if len(text) < 2 || strings.ToUpper(text[:2]) == text[:2] {
		return text // keep acronyms such as "OCI"
	}
	return strings.ToLower(text[:1]) + text[1:]
}

